const nav=[['dashboard','نمای کلی',LayoutDashboard],['members','اعضا',Users],['memberships','عضویت‌ها',CreditCard],['attendance','حضور و غیاب',CalendarCheck],['programs','برنامه تمرینی',Dumbbell],['nutrition','برنامه غذایی',Utensils],['progress','پیشرفت اعضا',Activity],['access','تیم باشگاه',UserRound],['products','فروشگاه',ShoppingBag],['orders','سفارش‌ها',Package],['payments','پرداخت‌ها',CreditCard],['reports','گزارش‌ها',ChartNoAxesCombined],['crm','پیگیری اعضا',HeartPulse],['automations','اتوماسیون',Zap],['notifications','اعلان‌ها',Bell],['settings','تنظیمات',Settings2]] as const;
