 const data=baseData&&paged&&listing?{...baseData,[collection]:listing.items}:baseData;
 useEffect(()=>{setCursor('');setHistory([]);setListing(null)},[view,query,branch,tid]);
 useEffect(()=>{const epoch=++pageEpoch.current;if(!baseData||!paged||!can(baseData.currentAccess.role,collection))return;setPageBusy(true);const timer=setTimeout(()=>{const params=new URLSearchParams({q:query,branch,cursor,limit:'50'});if(view==='nutrition'||view==='programs')params.set('kind',view==='nutrition'?'nutrition':'workout');api('page/'+collection+'?'+params).then(r=>{if(epoch===pageEpoch.current)setListing(r)}).catch(e=>{if(epoch===pageEpoch.current)toast.error(e.message)}).finally(()=>{if(epoch===pageEpoch.current)setPageBusy(false)})},200);return()=>{clearTimeout(timer);pageEpoch.current++}},[baseData,view,query,branch,tid,cursor,api,collection,paged]);
 const refresh=useCallback(async()=>{if(!tid)return;const epoch=++requestEpoch.current;setLoading(true);setError('');try{const state=await api('state');if(epoch===requestEpoch.current)setData(state);}catch(e){if(epoch===requestEpoch.current)setError((e as Error).message)}finally{if(epoch===requestEpoch.current)setLoading(false)}},[tid,api]);
 useEffect(()=>{api('bootstrap','GET',undefined,'').then(b=>{setBoot(b);if(b.tenants[0])setTid(b.tenants[0].id);else setLoading(false)}).catch(e=>{setError(e.message);setLoading(false)});const preference=localStorage.getItem('fitspace-theme');setDark(preference==='dark');},[]);
 useEffect(()=>{document.documentElement.classList.toggle('dark',dark);localStorage.setItem('fitspace-theme',dark?'dark':'light')},[dark]);
 useEffect(()=>{setData(null);setBranch('all');setCart([]);refresh()},[tid]);
 useEffect(()=>{setQuery('');setDetail(null);if(view==='platform'&&boot?.admin)api('platform').then(r=>setPlatform(r.tenants)).catch(e=>toast.error(e.message))},[view,boot?.admin]);
 const go=(v:string)=>router.push(v==='dashboard'?'/':'/'+v);
 const act=async(path:string,method:string,body:any)=>{setBusy(true);try{const r=await api(path,method,body);await refresh();toast.success('با موفقیت ثبت شد');return r;}catch(e){toast.error((e as Error).message);throw e;}finally{setBusy(false)}};
 const createGym=async(name:string)=>{setBusy(true);try{const r=await api('tenants','POST',{name},'');const b=await api('bootstrap','GET',undefined,'');setBoot(b);setTid(r.id);setModal(null);go('dashboard');toast.success('باشگاه شما آماده است.');}catch(e){toast.error((e as Error).message)}finally{setBusy(false)}};
 const role=data?.currentAccess?.role||'owner',isMember=role==='member',isTrainer=role==='trainer';
