 const access=data?.currentAccess||{}, currentRole=access.role||'owner';
 const allowedNav=nav.filter(([key])=>can(currentRole,navDomain[key]||key)&&(!['products','orders'].includes(key)||data?.tenant?.entitlements?.store));
 const heading=nav.find(n=>n[0]===view)?.[1]||(view==='platform'?'مدیریت سامانه':'نمای کلی');
 const isAllowed=view==='platform'?boot.admin:can(currentRole,navDomain[view]||view);
 const activeMemberships=visible(data?.memberships||[]).filter(m=>['ACTIVE','EXPIRING_SOON'].includes(m.status));
